// @ts-check

import { Checkbox } from "@shared/components";
import { AutoUpdatePreferences } from "../auto-update-preferences";

/** @typedef {import("@shared/pages/settings").SettingsSection} SettingsSection */
/**
 * @typedef {Object} CheckState
 * @property {() => {checked?: boolean}} getState
 * @property {(bSilent?: boolean) => void} check
 * @property {(bSilent?: boolean) => void} uncheck
 */

/**
 * Whether inserting a citation updates the other citations and the
 * bibliography: the settings Zotero adds to the settings page.
 * @implements {SettingsSection}
 */
class AutoUpdateSettings {
    constructor() {
        this._citations = new Checkbox("autoUpdateCitations", {
            label: "Update other citations when inserting a new one",
        });
        this._bibliography = new Checkbox("autoUpdateBibliography", {
            label: "Update the bibliography when inserting a citation",
        });
    }

    show() {
        setChecked(this._citations, AutoUpdatePreferences.shouldUpdateCitations());
        setChecked(this._bibliography, AutoUpdatePreferences.shouldUpdateBibliography());
    }

    /** @returns {boolean} */
    isChanged() {
        return (
            isChecked(this._citations) !== AutoUpdatePreferences.shouldUpdateCitations() ||
            isChecked(this._bibliography) !== AutoUpdatePreferences.shouldUpdateBibliography()
        );
    }

    save() {
        AutoUpdatePreferences.setShouldUpdateCitations(isChecked(this._citations));
        AutoUpdatePreferences.setShouldUpdateBibliography(isChecked(this._bibliography));
    }

    /** @param {() => void} callback */
    subscribe(callback) {
        this._citations.subscribe(function () {
            callback();
        });
        this._bibliography.subscribe(function () {
            callback();
        });
    }
}

/** @param {CheckState} checkbox */
function isChecked(checkbox) {
    return !!checkbox.getState().checked;
}

/**
 * @param {CheckState} checkbox
 * @param {boolean} checked
 */
function setChecked(checkbox, checked) {
    if (checked) {
        checkbox.check(true);
    } else {
        checkbox.uncheck(true);
    }
}

export { AutoUpdateSettings };
